const req=$('Alert Request').first().json.body||{};
const needles=[req.city,req.district,req.state].filter(Boolean).map(x=>String(x).toLowerCase().replace(/[_-]/g,' ').trim());
const clean=s=>String(s||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();
const items=$input.all().map((i,idx)=>{const a=i.json||{};const title=clean(a.title),summary=clean(a.contentSnippet||a.content||a.description||''),creator=clean(a.creator||a.author||'NDMA SACHET');const hay=(title+' '+summary+' '+creator).toLowerCase().replace(/[_-]/g,' ');return{title,summary,source:creator||'NDMA SACHET CAP',link:a.link||a.guid||'',date:a.isoDate||a.pubDate||'',hay,idx}});
let matched=needles.length?items.filter(a=>needles.some(n=>n.length>2&&a.hay.includes(n))):items;
matched=matched.slice(0,8).map(({hay,idx,...a})=>a);
return [{json:{official:true,source:'NDMA SACHET CAP/RSS',feedUrl:'https://sachet.ndma.gov.in/cap_public_website/rss/rss_india.xml',locationQuery:{city:req.city||'',district:req.district||'',state:req.state||''},alerts:matched,matched:matched.length,totalFeedItems:items.length,refreshedAt:new Date().toISOString(),note:'Location matching is text-based for this prototype; always open the source alert for authoritative geography and instructions.'}}];
